import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    # First token is ignored (n), second is m
    # data[0] is n, data[1] is m
    m = int(data[1])

    # The rest are group sizes
    gs = list(map(int, data[2:]))

    b = 0
    res = 0

    for g in gs:
        if b + g > m:
            res += 1
            b = g
        else:
            b += g

    if b > 0:
        res += 1

    sys.stdout.write(str(res))

if __name__ == "__main__":
    solve()

